// Never discard an authorized pending response merely because raw RX arrived.
// Give the single RX owner at most 1ms to compose its newer replacement. A
// protected one-shot bypasses handoff; active hardware traffic is untouched.
static bool p4_twai_immediate_newer_queued(twai_obj_t *obj,
                                           const p4_twai_priority_guard_t *guard)
{
    const p4_twai_rx_boundary_t *rx = &s_p4_rx_boundary[obj->controller_id];
    return guard->source == P4_TWAI_TX_SOURCE_R79_IMMEDIATE &&
           !guard->preserve_pending && guard->rx_sequence != 0 &&
           rx->latestQueuedMux1 != 0 && rx->latestQueuedMux1 != guard->rx_sequence &&
           rx->completedMux1 != rx->latestQueuedMux1;
}

static bool p4_twai_immediate_handoff_wait(twai_obj_t *obj)
{
    p4_twai_priority_slot_t *slot = &s_p4_priority[obj->controller_id];
    if (!p4_twai_immediate_newer_queued(obj, &slot->guard)) return false;
    const uint64_t now = (uint64_t)esp_timer_get_time();
    if (!slot->handoffWaiting) {
        slot->handoffWaiting = true;
        slot->handoffStartedUs = now;
    }
    return now - slot->handoffStartedUs < 1000u;
}

